<template><div class="fade-in"><div class="page-header"><h2>CỬA HÀNG GYMPRO</h2><el-badge :value="cartCount" :hidden="!cartCount"><el-button @click="tab='cart'">Giỏ hàng</el-button></el-badge></div>
<el-tabs v-model="tab" @tab-change="loadTab"><el-tab-pane label="Sản phẩm" name="products"><div class="filters"><el-select v-model="category" clearable placeholder="Danh mục" @change="loadProducts"><el-option label="Thực phẩm bổ sung" value="SUPPLEMENT"/><el-option label="Đồ ăn" value="FOOD"/><el-option label="Dụng cụ" value="EQUIPMENT"/></el-select><el-input v-model="keyword" placeholder="Tìm sản phẩm" clearable @keyup.enter="loadProducts"/><el-button @click="loadProducts">Tìm</el-button></div>
<div class="product-grid"><el-card v-for="p in products" :key="p.id" class="product"><img :src="p.imageUrl||fallback"/><el-tag v-if="p.recommended" type="success">Phù hợp với mục tiêu của bạn</el-tag><h3>{{p.name}}</h3><small>{{cat(p.category)}} · Còn {{p.stock}}</small><p>{{p.description}}</p><div class="price"><del v-if="p.salePrice">{{money(p.price)}}</del> {{money(p.salePrice||p.price)}}</div><el-button type="primary" :disabled="p.stock<=0" @click="add(p)">{{p.stock?'Thêm vào giỏ':'Hết hàng'}}</el-button></el-card></div></el-tab-pane>
<el-tab-pane label="Giỏ hàng" name="cart"><el-empty v-if="!cart.length" description="Giỏ hàng đang trống"/><el-card v-else><div v-for="i in cart" :key="i.cartItemId" class="cart-row"><div><b>{{i.name}}</b><div>{{money(i.unitPrice)}} × {{i.quantity}}</div></div><el-input-number :model-value="i.quantity" :min="1" :max="i.stock" @change="q=>changeQty(i,q)"/><b>{{money(i.lineTotal)}}</b><el-button type="danger" text @click="remove(i)">Xóa</el-button></div><div class="total">Tạm tính: {{money(cartTotal)}}</div><el-button type="primary" size="large" @click="checkoutOpen=true">Đặt hàng</el-button></el-card></el-tab-pane>
<el-tab-pane label="Đơn hàng" name="orders"><el-empty v-if="!orders.length" description="Chưa có đơn hàng"/><el-card v-for="o in orders" :key="o.id" class="order"><div class="order-head"><b>Đơn #{{o.id}}</b><el-tag>{{status(o.status)}}</el-tag><b>{{money(o.total)}}</b></div><div>{{o.items.map(i=>`${i.productName} × ${i.quantity}`).join(', ')}}</div><div class="muted">{{new Date(o.createdAt).toLocaleString('vi-VN')}} · {{o.shippingAddress}}</div><el-button v-if="o.status==='PENDING_PAYMENT'" type="primary" @click="showPay(o)">Thanh toán</el-button><el-button v-if="o.status==='PENDING_PAYMENT'" @click="cancel(o)">Hủy đơn</el-button></el-card></el-tab-pane></el-tabs>
<el-dialog v-model="checkoutOpen" title="Thông tin nhận hàng" width="520"><el-form label-position="top"><el-form-item label="Người nhận"><el-input v-model="checkout.receiverName"/></el-form-item><el-form-item label="Số điện thoại"><el-input v-model="checkout.phone"/></el-form-item><el-form-item label="Địa chỉ giao hàng"><el-input v-model="checkout.shippingAddress" type="textarea"/></el-form-item><el-form-item label="Ghi chú"><el-input v-model="checkout.note"/></el-form-item></el-form><template #footer><el-button @click="checkoutOpen=false">Hủy</el-button><el-button type="primary" @click="placeOrder">Tạo đơn chuyển khoản</el-button></template></el-dialog>
<el-dialog v-model="payOpen" title="Thanh toán chuyển khoản" width="520" center><div v-if="payOrder" class="pay"><h3>Đơn #{{payOrder.id}} · {{money(payOrder.total)}}</h3><img :src="qrSrc||payOrder.qrCodeUrl"/><p>Nội dung bắt buộc: <b>{{payOrder.transferCode}}</b></p><p>QR có hiệu lực 15 phút. Hệ thống tự xác nhận qua SePay.</p></div></el-dialog></div></template>
<script setup>import{ref,computed,onMounted,watch}from'vue';import{shopAPI}from'@/api';import{ElMessage,ElMessageBox}from'element-plus';import QRCode from'qrcode';
const tab=ref('products'),products=ref([]),cart=ref([]),orders=ref([]),category=ref(''),keyword=ref(''),checkoutOpen=ref(false),payOpen=ref(false),payOrder=ref(null),qrSrc=ref('');const fallback='https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=800&q=70';const checkout=ref({receiverName:'',phone:'',shippingAddress:'',note:''});const cartCount=computed(()=>cart.value.reduce((s,i)=>s+i.quantity,0)),cartTotal=computed(()=>cart.value.reduce((s,i)=>s+i.lineTotal,0));const money=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(v||0);const cat=v=>({SUPPLEMENT:'Thực phẩm bổ sung',FOOD:'Đồ ăn',EQUIPMENT:'Dụng cụ'})[v];const status=v=>({PENDING_PAYMENT:'Chờ thanh toán',PAID:'Đã thanh toán',PREPARING:'Đang chuẩn bị',SHIPPING:'Đang giao',DELIVERED:'Đã giao',COMPLETED:'Hoàn thành',CANCELLED:'Đã hủy',EXPIRED:'Hết hạn'})[v]||v;
async function loadProducts(){products.value=(await shopAPI.products({category:category.value||undefined,keyword:keyword.value||undefined})).data||[]}async function loadCart(){cart.value=(await shopAPI.cart()).data||[]}async function loadOrders(){orders.value=(await shopAPI.orders()).data||[]}async function loadTab(){if(tab.value==='cart')await loadCart();if(tab.value==='orders')await loadOrders()}async function add(p){await shopAPI.addCart(p.id);ElMessage.success('Đã thêm vào giỏ');await loadCart()}async function changeQty(i,q){await shopAPI.updateCart(i.cartItemId,q);await loadCart()}async function remove(i){await shopAPI.removeCart(i.cartItemId);await loadCart()}async function placeOrder(){const r=await shopAPI.checkout(checkout.value);checkoutOpen.value=false;await loadCart();tab.value='orders';await loadOrders();showPay(r.data)}async function showPay(o){payOrder.value=o;qrSrc.value=o.qrRawPayload?await QRCode.toDataURL(o.qrRawPayload,{width:260}):'';payOpen.value=true}async function cancel(o){await ElMessageBox.confirm('Hủy đơn và hoàn lại tồn kho?','Xác nhận');await shopAPI.cancelOrder(o.id);await loadOrders()}onMounted(async()=>{await Promise.all([loadProducts(),loadCart()])});watch(payOpen,v=>{if(!v)loadOrders()});</script>
<style scoped>.filters{display:flex;gap:10px;margin-bottom:18px}.filters>*{max-width:240px}.product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:16px}.product img{width:100%;height:150px;object-fit:cover;border-radius:12px}.product h3{margin:10px 0 4px}.product p{height:42px;overflow:hidden;color:var(--c-text2);font-size:.82rem}.price{font-weight:800;color:var(--c-accent);font-size:1.1rem;margin:10px 0}.price del{color:var(--c-text3);font-size:.8rem}.cart-row,.order-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--c-border2)}.total{text-align:right;font-size:1.2rem;font-weight:800;margin:16px}.order{margin-bottom:12px}.order>*{margin-bottom:8px}.pay{text-align:center}.pay img{width:280px;max-width:100%}@media(max-width:700px){.filters{flex-wrap:wrap}.cart-row{flex-wrap:wrap}}</style>
